select cron.unschedule(jobid) from cron.job where jobname='powerhouse-content-orchestrator-daily';
select cron.schedule('powerhouse-content-orchestrator-daily','12 6 * * *', $$select net.http_post(url := 'https://adhjwmvyoixzjtmiroln.supabase.co/functions/v1/powerhouse-content-orchestrator', headers := jsonb_build_object('content-type','application/json','x-powerhouse-token',(select decrypted_secret from vault.decrypted_secrets where name='powerhouse_daily_scheduler_token' order by created_at desc limit 1)), body := jsonb_build_object('runDate',(now() at time zone 'Europe/Amsterdam')::date::text), timeout_milliseconds := 120000);$$);
